import React from "react"
import type { ComponentType, SVGProps } from "react"
import {
    CalendarBlankIcon,
    GithubLogoIcon,
    GlobeIcon,
    HandshakeIcon,
    LinkedinLogoIcon,
    MapPinIcon,
    PencilSimpleIcon,
    UserCheckIcon,
    UserPlusIcon,
} from "@phosphor-icons/react"
import { Divider } from "@sb-components/atoms/display/Divider/Divider"
import { ProfileRankAvatar } from "./ProfileRankAvatar"
import { ProfileFollowers } from "./ProfileFollowers"
import { ProfileBadges } from "./ProfileBadges"
import { ShareProfileButton } from "./ShareProfileButton"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import type { ButtonVariant } from "@sb-components/atoms/buttons/Button/Button"
import { EnumChip, type EnumChipEntry } from "@sb-components/composites/chips/EnumChip/EnumChip"
import { InlineIconLabel } from "@sb-components/composites/text/InlineIconLabel/InlineIconLabel"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `ProfileHero` ΓÇö the identity sidebar for a person's profile page:
 * rank-framed avatar, name/@handle/role, bio, location + work-mode, follower
 * and badge social proof, one primary CTA (hire/follow/edit) + share, and a
 * github/linkedin/website/joined meta list. Composed from `SurfaceCard` around
 * `StackV`/`StackH`/`Cluster` holding `Avatar`/`Typography`/`Chip`/`Button`/
 * `Divider` plus `EnumChip`/`InlineIconLabel`. Two leaves: `Default` (every
 * optional row present; CTA/skeleton/follow-state are content states) and
 * `Minimal` (no rank/role/bio/location/work-mode/badges/social links ΓÇö losing
 * those removes real nodes, earning its own leaf).
 */

/** An icon passed as a COMPONENT (e.g. a Phosphor `*Icon`), rendered at the tile's own scale. Declared locally per atom convention (┬º5.0) rather than importing one library's type. */
type IconComponent = ComponentType<SVGProps<SVGSVGElement> & { weight?: "regular" | "bold" }>

/** How this person works ΓÇö the block owns the label wording (┬º14d.1), the caller only says which one. */
export type ProfileWorkMode = "remote" | "onsite" | "hybrid"

/** External profile links. Each is optional; an absent one simply drops its meta row. */
export interface ProfileSocialLinks {
    /** GitHub profile URL. */
    github?: string
    /** LinkedIn profile URL. */
    linkedin?: string
    /** Personal site/portfolio URL. */
    website?: string
}

/** One achievement/verification badge earned by this person. */
export interface ProfileBadge {
    /** Stable id ΓÇö used as the chip's React key. */
    id: string
    /** Badge label, already worded by the caller's domain (e.g. "Top mentor"). */
    label: string
    /** Optional leading glyph for the badge chip. */
    icon?: IconComponent
}

/** The person this hero profiles ΓÇö plain data, the block builds the sidebar from it. */
export interface ProfileHeroUser {
    /** Stable id (not rendered; kept for parity with other domain-user shapes). */
    id: string
    /** Full display name. */
    fullName: string
    /** Handle WITHOUT the leading `@` ΓÇö the block adds it (┬º14d.1). */
    handle: string
    /** Role/title line under the name. Row disappears when absent. */
    roleTitle?: string
    /** Short bio/about text. Row disappears when absent. */
    bio?: string
    /** Free-text location (e.g. "Hanoi, Vietnam"). Row disappears when absent. */
    location?: string
    /** How this person works. Row disappears when absent. */
    workMode?: ProfileWorkMode
    /** Photo URL. Empty/missing ΓåÆ `Avatar`'s own fallback chain, never a blank frame. */
    avatarUrl?: string
    /** Leaderboard-style standing (1 = top). Absent ΓåÆ no rank frame/caption at all. */
    rank?: number
    /** Total followers. Absent renders as `0` (a real, known count of nothing). */
    followersCount?: number
    /** Achievement badges earned. Empty/absent ΓåÆ the badges row disappears entirely. */
    badges?: ReadonlyArray<ProfileBadge>
    /** ISO date string this person joined. Required ΓÇö every profile has one. */
    joinedAt: string
    /** External links. Absent/all-empty ΓåÆ the social rows of the meta list disappear. */
    social?: ProfileSocialLinks
}

/** Props for {@link ProfileHero}. */
export interface ProfileHeroProps {
    /** The profiled person. */
    user: ProfileHeroUser
    /** `true` ΓåÆ the viewer IS this person: the primary CTA becomes "Edit profile", follow/hire never show. */
    isSelf?: boolean
    /** `true` (and not `isSelf`) ΓåÆ the primary CTA becomes "Hire me" instead of follow. */
    canHire?: boolean
    /** Whether the viewer already follows this person. Ignored when `isSelf`/`canHire`. */
    following?: boolean
    /** `true` ΓåÆ the follow CTA shows its busy state while the toggle is in flight. */
    isFollowPending?: boolean
    /** Fired when the viewer toggles follow (only reachable when neither `isSelf` nor `canHire`). */
    onToggleFollow?: () => void
    /** Fired when the viewer presses "Hire me" (only reachable when `canHire` and not `isSelf`). See file header, judgement call 3. */
    onHire?: () => void
    /** Fired when the profile owner presses "Edit profile" (only reachable when `isSelf`). */
    onEdit?: () => void
    /** Fired when the share action is pressed. */
    onShare?: () => void
    /** `true` ΓåÆ every real part switches to its own shimmer; the profile stops accepting presses. */
    isSkeleton?: boolean
}

interface PrimaryAction {
    label: string
    variant: ButtonVariant
    prefixIcon: IconComponent
    onPress?: () => void
    isPending?: boolean
}

/** Inputs {@link resolvePrimaryAction} needs to pick the one CTA slot. */
interface ResolvePrimaryActionParams {
    isSelf: boolean
    canHire: boolean
    following: boolean
    isFollowPending: boolean
    onEdit?: () => void
    onHire?: () => void
    onToggleFollow?: () => void
}

const resolvePrimaryAction = (params: ResolvePrimaryActionParams): PrimaryAction => {
    const { isSelf, canHire, following, isFollowPending, onEdit, onHire, onToggleFollow } = params
    if (isSelf) {
        return { label: "Edit profile", variant: "secondary", prefixIcon: PencilSimpleIcon, onPress: onEdit }
    }
    if (canHire) {
        return { label: "Hire me", variant: "primary", prefixIcon: HandshakeIcon, onPress: onHire }
    }
    return {
        label: following ? "Following" : "Follow",
        variant: following ? "secondary" : "primary",
        prefixIcon: following ? UserCheckIcon : UserPlusIcon,
        onPress: onToggleFollow,
        isPending: isFollowPending,
    }
}

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// Meta list ΓÇö social links (as text-links) + joined date (plain).
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/** One entry of the social meta list ΓÇö the block's own icon + label per platform. */
interface ProfileSocialMetaEntry {
    key: keyof ProfileSocialLinks
    icon: IconComponent
    label: string
}

/** The block's own label per platform (┬º14d.1) ΓÇö the caller only supplies the URL. */
const SOCIAL_META: ReadonlyArray<ProfileSocialMetaEntry> = [
    { key: "github", icon: GithubLogoIcon, label: "GitHub" },
    { key: "linkedin", icon: LinkedinLogoIcon, label: "LinkedIn" },
    { key: "website", icon: GlobeIcon, label: "Personal site" },
]

/** `Intl`-formatted "Month M, YYYY" from an ISO date string. Empty input ΓåÆ empty string (no bogus date printed). */
const formatJoinedDate = (isoDate: string): string => {
    const date = new Date(isoDate)
    if (Number.isNaN(date.getTime())) return ""
    return new Intl.DateTimeFormat("vi-VN", { month: "long", year: "numeric" }).format(date)
}

/** How this person works, worded by the block (┬º14d.1). */
const WORK_MODE_MAP: Record<ProfileWorkMode, EnumChipEntry> = {
    remote: { label: "Remote" },
    onsite: { label: "Onsite" },
    hybrid: { label: "Hybrid", color: "accent" },
}

/**
 * The bare identity sidebar. See the file header for the reuse contract and the
 * four judgement calls.
 *
 * @param props - {@link ProfileHeroProps}
 */
const ProfileHero = ({
    user,
    isSelf = false,
    canHire = false,
    following = false,
    isFollowPending = false,
    onToggleFollow,
    onHire,
    onEdit,
    onShare,
    isSkeleton = false,
}: ProfileHeroProps) => {
    const { fullName, handle, roleTitle, bio, location, workMode, avatarUrl, rank, followersCount, badges, joinedAt, social } = user

    const action = resolvePrimaryAction({ isSelf, canHire, following, isFollowPending, onEdit, onHire, onToggleFollow })
    const hasBadgesRow = isSkeleton || Boolean(badges && badges.length > 0)
    const hasLocationRow = isSkeleton || Boolean(location) || Boolean(workMode)

    const socialLinks = social ?? {}
    const socialEntries = SOCIAL_META.filter((entry) => Boolean(socialLinks[entry.key]))
    const hasMetaList = isSkeleton || socialEntries.length > 0 || Boolean(joinedAt)

    return (
        <SurfaceCard
            identity={{ tier: "block", component: "ProfileHero" }}
            body={() => (
                <StackV
                    principle="block-boundary"
                    explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major profile hero sections rather than nested groups."
                    isSkeleton={isSkeleton}
                    items={[
                        () => (
                            <StackV
                                principle="card-caption"
                                explain="Holds caption text under card media so the caption stays attached to the image above it."
                                isSkeleton={isSkeleton}
                                items={[
                                    () => (
                                        <ProfileRankAvatar
                                            name={fullName}
                                            avatarUrl={avatarUrl}
                                            rank={rank}
                                            isSkeleton={isSkeleton}
                                        />
                                    ),
                                    () => (
                                            <StackV
                                                principle="name-handle"
                                                explain="Display name with handle ΓÇö not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                                isSkeleton={isSkeleton}
                                                items={[
                                                    () => (
                                                        <Typography
                                                            size="h5"
                                                            weight="bold"
                                                            align="center"
                                                            isSkeleton={isSkeleton}
                                                            text={fullName}

                                                        />
                                                    ),
                                                    () => (
                                                        <Typography
                                                            size="sm"
                                                            color="muted"
                                                            align="center"
                                                            isSkeleton={isSkeleton}
                                                            text={isSkeleton ? undefined : `@${handle}`}

                                                        />
                                                    ),
                                                    ...(isSkeleton || roleTitle
                                                        ? [
                                                            () => (
                                                                <Typography
                                                                    size="sm"
                                                                    weight="medium"
                                                                    align="center"
                                                                    isSkeleton={isSkeleton}
                                                                    text={roleTitle}

                                                                />
                                                            ),
                                                        ]
                                                        : []),
                                                ]}
                                            />
                                        ),
                                    ]}
                                />
                            ),

                            ...(isSkeleton || bio
                                ? [
                                    () => (
                                        <Typography
                                            size="sm"
                                            color="muted"
                                            align="center"
                                            lineClamp={3}
                                            isSkeleton={isSkeleton}
                                            text={bio}

                                        />
                                    ),
                                ]
                                : []),

                            ...(hasLocationRow
                                ? [
                                    () => (
                                        <Cluster
                                            gap={3}
                                            principle="chip-row"
                                            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                            items={[
                                                ...(isSkeleton || location
                                                    ? [
                                                        () => (
                                                            <InlineIconLabel
                                                                icon={MapPinIcon}
                                                                isSkeleton={isSkeleton}
                                                                label={location}
                                                            />
                                                        ),
                                                    ]
                                                    : []),
                                                ...(isSkeleton || workMode
                                                    ? [
                                                        () => (
                                                            <EnumChip
                                                                value={(workMode ?? "remote") as ProfileWorkMode}
                                                                map={WORK_MODE_MAP}
                                                                isSkeleton={isSkeleton}
                                                            />
                                                        ),
                                                    ]
                                                    : []),
                                            ]}
                                        />
                                    ),
                                ]
                                : []),

                            () => (
                                <StackH
                                    principle="sibling-stack"
                                    explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                    divider
                                    isSkeleton={isSkeleton}
                                    items={[
                                        () => <ProfileFollowers followersCount={followersCount} isSkeleton={isSkeleton} />,
                                        ...(hasBadgesRow
                                            ? [() => <ProfileBadges badges={badges} isSkeleton={isSkeleton} />]
                                            : []),
                                    ]}
                                />
                            ),

                            () => (
                                <StackH
                                    gap={3}
                                    isSkeleton={isSkeleton}
                                    items={[
                                        () => (
                                            <Button

                                                variant={action.variant}
                                                label={action.label}
                                                prefixIcon={action.prefixIcon}
                                                onPress={action.onPress}
                                                isPending={action.isPending}
                                                isSkeleton={isSkeleton}

                                            />
                                        ),
                                        () => <ShareProfileButton onShare={onShare} isSkeleton={isSkeleton} />,
                                    ]}
                                />
                            ),

                            ...(hasMetaList
                                ? [
                                    () => <Divider />,
                                    () => (
                                        <StackV
                                            gap={4}
                                            isSkeleton={isSkeleton}
                                            items={[
                                                ...(isSkeleton ? SOCIAL_META : socialEntries).map((entry) => () => (
                                                    <StackH
                                                        gap={2}
                                                        isSkeleton={isSkeleton}
                                                        items={[
                                                            () => (
                                                                <span aria-hidden className="inline-flex shrink-0 text-muted [&_svg]:size-4">
                                                                    <entry.icon />
                                                                </span>
                                                            ),
                                                            () => (
                                                                <Typography
                                                                    size="xs"
                                                                    isLink={!isSkeleton}
                                                                    href={isSkeleton ? undefined : socialLinks[entry.key]}
                                                                    isSkeleton={isSkeleton}
                                                                    truncate
                                                                    text={isSkeleton ? undefined : entry.label}

                                                                />
                                                            ),
                                                        ]}
                                                    />
                                                )),
                                                () => (
                                                    <InlineIconLabel
                                                        icon={CalendarBlankIcon}
                                                        tone="default"
                                                        isSkeleton={isSkeleton}
                                                        label={isSkeleton ? undefined : `Joined ${formatJoinedDate(joinedAt)}`}
                                                    />
                                                ),
                                            ]}
                                        />
                                    ),
                                ]
                                : []),
                        ]}
                    />
                )}
            />
        </SurfaceCard>
    )
}

export { ProfileHero }

import { InputTextarea } from "@/components/atoms/forms"
import React from "react"
import type { ReactNode } from "react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { CommunityCommentRow } from "@/components/blocks/feed/CommunityCommentRow"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Button } from "@/components/atoms/buttons/Button"

import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"
import { ReactionType } from "@/modules/api/graphql/queries/types/discussion"
import type { QueryCommunityCommentNode } from "@/modules/api/graphql/queries/types/community-comments"

/** How many placeholder rows the co-located skeleton shows while the replies list loads. */
const SKELETON_REPLY_COUNT = 2

/** All display text, already localized by the connected {@link import("./index").CommunityCommentItem}; a story passes i18n keys. */
export interface CommunityCommentItemLabels {
    /** "Reply" toggle under the comment (only when signed in and the comment isn't deleted). */
    replyToggle: string
    /** "View N replies" ΓÇö shown when the reply list is collapsed. Already interpolated with the count. */
    viewReplies: string
    /** "Hide replies" ΓÇö shown when the reply list is open. */
    hideReplies: string
    /** Placeholder + accessible name for the reply textarea. */
    replyPlaceholder: string
    /** Submit button label on the reply box. */
    send: string
    /** Settled with zero replies ΓÇö the replies region's empty title. */
    repliesEmptyTitle: string
    /** Settled with a fetch error ΓÇö the replies region's error title. */
    repliesErrorTitle: string
    /** Retry-button label on the replies region's error state. */
    retry: string
}

/** Props for {@link _CommunityCommentItem} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface CommunityCommentItemProps {
    /** The top-level comment to render (with its reply controls). */
    comment: QueryCommunityCommentNode
    /** Whether the viewer is signed in (gates reply + reactions). */
    authenticated: boolean
    /** React to this top-level comment. Omit to render the reaction bar read-only. */
    onReact?: (type: ReactionType | null) => void

    /** Whether the reply textarea is open. */
    replyOpen: boolean
    /** Toggles {@link CommunityCommentItemProps.replyOpen}. */
    onToggleReplyOpen: () => void
    /** Current (controlled) reply draft. */
    replyBody: string
    /** Fired on every keystroke in the reply textarea. */
    onReplyBodyChange: (value: string) => void
    /** Submits {@link CommunityCommentItemProps.replyBody} as a reply. */
    onSubmitReply: () => void
    /** True while the reply mutation is in flight ΓÇö locks the send button. */
    isSubmittingReply?: boolean

    /** Whether the replies list is expanded. */
    repliesOpen: boolean
    /** Toggles {@link CommunityCommentItemProps.repliesOpen}. */
    onToggleReplies: () => void
    /** First load, nothing in hand ΓåÆ the replies region shimmers in place (co-located). Owned by the connected file. */
    repliesIsSkeleton?: boolean
    /** Settled with zero replies ΓåÆ the replies region's empty message. */
    repliesIsEmpty?: boolean
    /** Truthy ΓåÆ the replies region's error message (beats loading + empty). */
    repliesError?: unknown
    /** Retries the failed replies query. */
    onRetryReplies?: () => void
    /** The loaded replies, already resolved. */
    replies?: Array<QueryCommunityCommentNode>
    /** React to one of the replies. Omit to render every reply's reaction bar read-only. */
    onReactReply?: (replyId: string, type: ReactionType | null) => void

    labels: CommunityCommentItemLabels
}

/**
 * A top-level community comment with its reply affordances: react, reply (one level deep), and an
 * expandable list of its replies ΓÇö the presentational half of
 * {@link import("./index").CommunityCommentItem} (`tiers/split.md`). The replies region renders
 * error ΓåÆ skeleton ΓåÆ empty ΓåÆ content in that fixed order (BLOCK-8); `CommunityCommentRow` (the reply
 * row) takes no `isSkeleton` of its own, so while shimmering the SAME list position swaps in a bare
 * `Skeleton.ListRow` instead of threading a flag through it (`loading-and-skeleton.md` ┬º1's stated
 * exception).
 *
 * @param props - {@link CommunityCommentItemProps}
 */
export const _CommunityCommentItem = ({
    comment,
    authenticated,
    onReact,
    replyOpen,
    onToggleReplyOpen,
    replyBody,
    onReplyBodyChange,
    onSubmitReply,
    isSubmittingReply = false,
    repliesOpen,
    onToggleReplies,
    repliesIsSkeleton = false,
    repliesIsEmpty = false,
    repliesError,
    onRetryReplies,
    replies = [],
    onReactReply,
    labels,
}: CommunityCommentItemProps) => {
    const showReplyToggle = authenticated && !comment.isDeleted
    const showViewReplies = comment.replyCount > 0

    const actions = showReplyToggle || showViewReplies
        ? (
            <StackH
                principle="flex-action"
                explain="Reply and view-replies are peer controls the reader acts on ΓÇö not chip-row, because these are press targets rather than display tags."
                items={[
                ...(showReplyToggle ? [() => (
                    <Typography size="xs" color="muted" isButton text={labels.replyToggle} onPress={onToggleReplyOpen} />
                )] : []),
                ...(showViewReplies ? [() => (
                    <Typography
                        size="xs"
                        color="accent-soft"
                        isButton
                        text={repliesOpen ? labels.hideReplies : labels.viewReplies}
                        onPress={onToggleReplies}
                    />
                )] : []),
            ]} />
        )
        : undefined

    // error beats a stale skeleton flag; empty only once settled (BLOCK-8)
    let repliesContent: ReactNode = null
    if (repliesOpen) {
        if (repliesError) {
            repliesContent = (
                <AsyncContentError title={labels.repliesErrorTitle} onRetry={onRetryReplies} retryLabel={labels.retry} />
            )
        } else if (!repliesIsSkeleton && repliesIsEmpty) {
            repliesContent = <AsyncContentEmpty title={labels.repliesEmptyTitle} />
        } else {
            // co-located: SAME row list, placeholder rows while shimmering, real rows once resolved.
            // `CommunityCommentRow` has no `isSkeleton` of its own (┬º1's exception) ΓÇö the placeholder
            // swaps in a bare `Skeleton.ListRow` at the same position instead of threading a flag.
            const rows = repliesIsSkeleton
                ? Array.from({ length: SKELETON_REPLY_COUNT }, () => () => (
                    <Skeleton.ListRow withSubtitle withTrailing={false} />
                ))
                : replies.map((reply) => () => (
                    <CommunityCommentRow
                        comment={reply}
                        onReact={authenticated ? (type: ReactionType | null) => onReactReply?.(reply.id, type) : undefined}
                    />
                ))
            repliesContent = (
                <StackV
                    principle="sibling-stack"
                    explain="Same-kind peer stack ΓÇö not group-boundary, because reply rows are repeating siblings rather than section groups."
                    items={rows}
                />
            )
        }
    }

    return (
        <StackV
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
            identity={{ tier: "block", component: "CommunityCommentItem" }}
            items={[
                () => (
                    <CommunityCommentRow comment={comment} onReact={authenticated ? onReact : undefined} actions={actions} />
                ),
                ...(replyOpen && authenticated ? [() => (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                        nested items={[
                            () => (
                                <InputTextarea
                                    rows={2}
                                    value={replyBody}
                                    onValueChange={onReplyBodyChange}
                                    placeholder={labels.replyPlaceholder}
                                    ariaLabel={labels.replyPlaceholder}
                                    variant="secondary"
                                />
                            ),
                            () => (
                                <Box principle="push-end" className="ml-auto w-fit"
                                    explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                                    <Button
                                        variant="primary"
                                        size="sm"
                                        isPending={isSubmittingReply}
                                        isDisabled={!replyBody.trim()}
                                        onPress={onSubmitReply}
                                        label={labels.send}
                                    />
                                </Box>
                            ),
                        ]} />
                )] : []),
                ...(repliesOpen ? [() => (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                        nested body={() => repliesContent}  />
                )] : []),
            ]} />
    )
}

"use client"

import { InputTextarea } from "@/components/atoms/forms"
import React, { useCallback, useState } from "react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Button } from "@/components/atoms/buttons/Button"
import { Divider } from "@/components/atoms/display/Divider"

import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"
import { CommunityCommentItem } from "@/components/blocks/community/CommunityCommentItem"
import type { QueryCommunityCommentNode } from "@/modules/api/graphql/queries/types/community-comments"

/** How many placeholder rows the co-located skeleton shows while the thread's first load is in flight. */
const SKELETON_ROW_COUNT = 3

/** All display text, already localized by the connected `CommunityCommentThread`; a story passes i18n keys. */
export interface CommunityCommentThreadLabels {
    /** Placeholder + aria-label of the top-level composer. */
    composerPlaceholder: string
    /** Submit button label. */
    send: string
    /** Shown when the thread has settled with zero comments. */
    emptyTitle: string
    /** Shown when the thread has settled with a fetch error, nothing in hand. */
    errorTitle: string
    /** Retry button label, paired with `onRetry`. */
    retry: string
}

/** Props for {@link _CommunityCommentThread} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface CommunityCommentThreadProps {
    /** Post whose comments are shown ΓÇö threaded to each row for its own reply/react calls. */
    postId: string
    /** Whether the viewer is signed in (gates the composer + reactions). */
    authenticated: boolean
    /**
     * First load, nothing in hand ΓåÆ the list shimmers in place (co-located, no parallel
     * tree). Owned by the connected file (loading-and-skeleton.md).
     */
    isSkeleton?: boolean
    /** Settled with zero comments ΓåÆ the empty message. */
    isEmpty?: boolean
    /** Truthy ΓåÆ the error message (beats a stale loading flag). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler, paired with `labels.retry` on the error branch. */
    onRetry?: () => void
    /** Top-level comments to render; ignored while `isSkeleton`. */
    comments?: Array<QueryCommunityCommentNode>
    /** Refresh the thread after a row-level change (reply/react) ΓÇö also bubbles up to the feed. */
    onItemChanged?: () => void
    /** Submit the composer's trimmed body; resolves `true` on success so the composer clears itself. */
    onSubmit: (body: string) => Promise<boolean>
    /** True while the create-comment mutation is in flight. */
    isSubmitting?: boolean
    labels: CommunityCommentThreadLabels
}

/**
 * Expandable comment thread under a community post: lists top-level comments (each with its own
 * reply + nested-replies controls via {@link CommunityCommentItem}), plus a composer for signed-in
 * users. The presentational half of {@link import("./index").CommunityCommentThread} ΓÇö error beats a
 * stale loading flag, empty only once settled, otherwise the ONE tree renders with `isSkeleton`
 * threaded down. `CommunityCommentItem` carries no `isSkeleton` of its own, so the loading branch
 * swaps in `Skeleton.ListRow` placeholders right where the real rows sit (loading-and-skeleton.md).
 * See `tiers/split.md` ΓÇö the connected `index.tsx` owns the fetch, the mutation, and i18n.
 *
 * @param props - {@link CommunityCommentThreadProps}
 */
export const _CommunityCommentThread = ({
    postId,
    authenticated,
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    comments = [],
    onItemChanged,
    onSubmit,
    isSubmitting = false,
    labels,
}: CommunityCommentThreadProps) => {
    const [composerValue, setComposerValue] = useState("")

    /** Submit the composer, then clear it only once the connected half confirms success. */
    const onComposerSubmit = useCallback(async () => {
        const trimmed = composerValue.trim()
        if (!trimmed) {
            return
        }
        const ok = await onSubmit(trimmed)
        if (ok) {
            setComposerValue("")
        }
    }, [composerValue, onSubmit])

    // Rows: `CommunityCommentItem` has no `isSkeleton` of its own, so while shimmering a matching
    // count of `Skeleton.ListRow` stands in, right in the same list position (co-located, not a
    // parallel tree) ΓÇö see `missingSkeletonSupport`.
    const rows = isSkeleton
        ? Array.from({ length: SKELETON_ROW_COUNT }, () => () => (
            <Skeleton.ListRow withSubtitle withTrailing={false} />
        ))
        : comments.map((comment) => () => (
            <CommunityCommentItem
                postId={postId}
                comment={comment}
                authenticated={authenticated}
                onChanged={onItemChanged}
            />
        ))

    // error beats a stale loading flag; empty only once settled (BLOCK-8 / loading-and-skeleton.md).
    let listBody: React.ReactNode
    if (error) {
        listBody = <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    } else if (!isSkeleton && isEmpty) {
        listBody = <AsyncContentEmpty title={labels.emptyTitle} />
    } else {
        listBody = (
            <StackV
                principle="sibling-stack"
                explain="Same-kind peer stack ΓÇö not group-boundary, because top-level comments are repeating siblings rather than section groups."
                isSkeleton={isSkeleton}
                items={rows}
            />
        )
    }

    return (
        <StackV
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
            identity={{ tier: "block", component: "CommunityCommentThread" }}
            items={[
                () => <Divider />,
                ...(authenticated ? [() => (
                    <StackV
                        principle="sibling-stack"
                        explain="Same-kind peer stack ΓÇö not group-boundary, because the composer field and send control are repeating siblings in one unit."
                        items={[
                        () => (
                            <InputTextarea
                                variant="secondary"
                                rows={2}
                                value={composerValue}
                                onValueChange={setComposerValue}
                                placeholder={labels.composerPlaceholder}
                                ariaLabel={labels.composerPlaceholder}
                            />
                        ),
                        () => (
                            <Box principle="push-end" className="ml-auto w-fit"
                                explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                                <Button
                                    variant="primary"
                                    size="sm"
                                    label={labels.send}
                                    isPending={isSubmitting}
                                    isDisabled={!composerValue.trim()}
                                    onPress={() => void onComposerSubmit()}
                                />
                            </Box>
                        ),
                    ]} />
                )] : []),
                () => listBody,
            ]}
        />
    )
}

import React from "react"
import { CheckCircleIcon, SparkleIcon, XCircleIcon } from "@phosphor-icons/react"
import { AiCategoryChip } from "@/components/blocks/chips/AiCategoryChip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH } from "@/components/frames/Stack"
import type { AiModelCategory } from "@/modules/api/graphql/queries/query-ai-models"

/** Props for {@link VerdictIcon}. */
export interface VerdictIconProps {
    /** `true` ΓåÆ green check; `false` ΓåÆ red x. */
    pass: boolean
}

/**
 * Pass/fail verdict glyph (green check / red x). Shared by the result selector
 * chips, the drawer trigger, the verdict chip, and the history rows.
 *
 * @param props - {@link VerdictIconProps}
 */
export const VerdictIcon = ({ pass }: VerdictIconProps) =>
    pass ? (
        <CheckCircleIcon aria-hidden focusable="false" className="size-4 shrink-0 text-success-soft-foreground" />
    ) : (
        <XCircleIcon aria-hidden focusable="false" className="size-4 shrink-0 text-danger-soft-foreground" />
    )

/** Props for {@link _ModelByline} ΓÇö presentational; the "graded by" prefix already resolved. */
export interface ModelBylineProps {
    /** The served model id. `null` ΓåÆ renders nothing (model not recorded). */
    model: string | null
    /** The model's resolved tier category. */
    category?: AiModelCategory
    /** Already-localized "graded by " prefix (with trailing space); omit to render the model name bare. */
    gradedByPrefix?: string
}

/**
 * Grading-model attribution: an accent sparkle + plain "graded by `<model>`" text,
 * followed by the model's tier chip. The model name is PLAIN TEXT (not a chip, not
 * mono) so it never sits chip-beside-chip with the tier chip ΓÇö the rule is "text,
 * then a chip beside it". Renders nothing when the served model wasn't recorded.
 *
 * @param props - {@link ModelBylineProps}
 */
export const _ModelByline = ({ model, category, gradedByPrefix }: ModelBylineProps) => {
    if (!model) {
        return null
    }
    return (
        <StackH
            identity={{ tier: "block", component: "GradingByline" }}
            principle="chip-row"
            explain="Model attribution text and its tier chip share one wrapping row ΓÇö not flex-action, because the chip is display metadata rather than a control."
            align="center"
            items={[
                () => (
                    <StackH
                        principle="icon-text"
                        explain="Sparkle glyph hugging the graded-by copy ΓÇö not separator-dot, because this is one labeled unit."
                        align="center"
                        items={[
                            () => (
                                <SparkleIcon
                                    aria-hidden
                                    focusable="false"
                                    className="size-4 shrink-0 text-accent-soft-foreground"
                                />
                            ),
                            () => (
                                <Typography
                                    size="sm"
                                    color="muted"
                                    text={`${gradedByPrefix ?? ""}${model}`}
                                />
                            ),
                        ]}
                    />
                ),
                ...(category ? [() => <AiCategoryChip category={category} />] : []),
            ]}
        />
    )
}

